/* ORA demo — results, dashboard, Risk Journey, configuration and modals */
(function () {
  const C = window.ORA, D = window.ORA_DATA, U = window.ORA_UI, I = window.ORA_I18N;
  const h = C.esc, ic = U.ic, L = I.L, tx = I.tx;

  U.stage[7] = function (a, ev) {
    const m = C.metrics(a);
    const rv = a.review; const ready = rv.findings && rv.photos && rv.consistency;
    const chk = (k, l, d) => `<label class="check" id="rv-${k}"><input type="checkbox" data-act="review" data-k="${k}" ${rv[k] ? 'checked' : ''}><span><b style="font-weight:600">${l}</b><br><span class="small mut">${d}</span></span></label>`;
    const lim = [];
    ev.reqs.filter(r => r.status !== 'capturada').forEach(r => lim.push(`${r.label}: ${C.PH_LBL[r.status].toLowerCase()}${r.res ? ' — ' + tx(r.res.note) : ''}`));
    a.processes.filter(p => p.status === 'desconocido').forEach(p => lim.push(`${tx(p.name)}: ${L('estado desconocido', 'status unknown')}`));
    ev.app.filter(x => (a.answers[x.q.id] || {}).value === 'Desconocido').forEach(x => lim.push(`${x.q.id}: ${L('respuesta desconocida', 'unknown answer')}`));
    const cover = a.photos.find(p => p.cover && p.inReport);
    const inRep = a.photos.filter(p => p.inReport).length;
    const RL = { sc: L('Escenarios', 'Scenarios'), hz: L('Horizonte', 'Horizon'), ow: L('Responsable sugerido', 'Suggested owner'), pr: L('Prioridad', 'Priority'), st: L('Estado', 'Status') };
    const roadmap = a.recs.map(r => `<tr><td class="rm-head"><b>${r.id}</b><span class="rm-title">${h(tx(r.title))}<span class="small mut">${L('Base', 'Basis')}: ${h(tx(r.basis) || r.sc.join(', '))}</span></span><span class="pill rm-pr ${r.pr === 'Alta' ? 'err' : 'warn'}">${h(tx(r.pr))}</span></td><td class="rm-desk">${h(tx(r.title))}<div class="small mut">${L('Base', 'Basis')}: ${h(tx(r.basis) || r.sc.join(', '))}</div></td><td data-label="${RL.sc}">${r.sc.map(x => { const s = a.scenarios.find(y => y.id === x); return s ? `<div class="row" style="gap:6px"><span>${x}</span>${U.lv(C.LEVEL(s.C, s.P))}</div>` : x; }).join('')}</td><td data-label="${RL.hz}">${h(tx(r.hz))}</td><td data-label="${RL.ow}">${h(tx(r.owner) || L('Por definir', 'TBD'))}</td><td class="rm-desk" data-label="${RL.pr}"><span class="pill ${r.pr === 'Alta' ? 'err' : 'warn'}">${h(tx(r.pr))}</span></td>
      <td data-label="${RL.st}"><select class="inp" id="rs-${r.id}" data-f="rec.${r.id}.st" aria-label="${r.id}" style="min-width:130px">${['Propuesta', 'Aceptada', 'En curso', 'Completada'].map(x => U.opt(x, tx(x), r.st)).join('')}</select></td></tr>`).join('');
    const pr = U.pdfState || {};
    const appr = a.reportStatus === 'Aprobado';
    return `<div class="grid2 g-13">
      <section class="box"><div class="box-head"><h3>${L('Revisión de cierre', 'Closing review')}</h3><span class="pill ${appr ? 'ok' : 'warn'}">${tx(a.reportStatus)} · v${a.reportVersion}</span></div>
        <div class="box-body"><div class="checks">
          ${chk('findings', L('Hallazgos y recomendaciones revisados', 'Findings and recommendations reviewed'), L('Cada recomendación está vinculada a un escenario, su evidencia y sus supuestos.', 'Each recommendation is linked to a scenario, its evidence and assumptions.'))}
          ${chk('photos', L('Fotografías autorizadas por el cliente', 'Photos authorized by the client'), inRep + L(' fotos marcadas para el informe; sin metadatos sensibles.', ' photos marked for the report; no sensitive metadata.'))}
          ${chk('consistency', L('Alcance, exclusiones y limitaciones confirmados', 'Scope, exclusions and limitations confirmed'), L(`${m.inc.length} procesos incluidos, ${m.outScope} fuera de alcance, ${m.na} no aplica, ${m.unkProc} desconocidos.`, `${m.inc.length} processes included, ${m.outScope} out of scope, ${m.na} not applicable, ${m.unkProc} unknown.`))}
        </div>
        <div class="note-info">${ic('info')}<span>${L('La evidencia faltante no bloquea la aprobación automáticamente (criterio pendiente de definición), pero se declara en el informe como limitación.', 'Missing evidence does not automatically block approval (criterion still to be defined), but it is declared in the report as a limitation.')}</span></div>
        <div class="row">${appr ? `<button class="btn ghost" data-act="draft">${L('Volver a borrador', 'Back to draft')}</button>` : `<button class="btn primary" id="rep-approve" data-act="approve" ${ready ? '' : 'disabled'}>${ic('shield')}${L('Aprobar informe', 'Approve report')}</button>`}${!ready && !appr ? `<span class="small mut">${L('Complete la revisión para aprobar.', 'Complete the review to approve.')}</span>` : ''}</div></div></section>
      <section class="box"><div class="box-head"><h3>${L('Informe ejecutivo PDF', 'Executive PDF report')}</h3><span class="pill">${appr ? L('Final', 'Final') : L('Marca de agua BORRADOR', 'DRAFT watermark')}</span></div>
        <div class="box-body">
          <div class="toc"><span>${L('Portada, alcance y resumen ejecutivo', 'Cover, scope and executive summary')}</span><span>${m.inc.length} ${L('procesos', 'processes')}</span><span>${L('Indicadores, matriz, barras y radar', 'KPIs, matrix, bars and radar')}</span><span>${m.scn.length} ${L('escenarios', 'scenarios')}</span><span>${L('Fichas de riesgo con evidencia', 'Risk sheets with evidence')}</span><span>${m.scn.length} ${L('fichas', 'sheets')}</span><span>${L('Evidencias fotográficas con pies', 'Captioned photo evidence')}</span><span>${inRep} ${L('fotos', 'photos')}</span><span>${L('Hoja de ruta de mitigación', 'Mitigation roadmap')}</span><span>${a.recs.length} ${L('acciones', 'actions')}</span><span>${L('Limitaciones y excepciones', 'Limitations and exceptions')}</span><span>${lim.length} ${L('ítems', 'items')}</span><span>${L('Anexo: respuestas del cuestionario', 'Annex: questionnaire answers')}</span><span>${m.appDone}/${m.appTotal}</span></div>
          <button class="btn primary" data-act="pdf" ${pr.busy ? 'disabled' : ''}>${ic('down')}${pr.busy ? L('Generando PDF…', 'Generating PDF…') : L('Generar y descargar PDF', 'Generate and download PDF')}</button>
          ${pr.done ? `<div class="pdf-result">${ic('check')}<span><b>${L('PDF generado', 'PDF generated')}:</b> ${pr.pages} ${L('páginas', 'pages')} · ${(pr.size / 1024 / 1024).toFixed(2)} MB · ${h(pr.name)}</span><span class="spacer"></span><button class="btn ghost sm" data-act="pdf-save">${L('Descargar de nuevo', 'Download again')}</button></div>${pr.msg ? `<p class="small mut">${h(pr.msg)}</p>` : ''}` : ''}
          ${pr.err ? `<div class="note-demo">${ic('alert')}<span>${h(pr.err)}</span></div>` : ''}
          <p class="hint">${L('El PDF se genera en el navegador con jsPDF, en el idioma activo, a partir de los mismos datos del dashboard. Claude pide confirmar la descarga.', 'The PDF is generated in the browser with jsPDF, in the active language, from the same data as the dashboard. Claude asks you to confirm the download.')}</p></div></section></div>
      <div class="grid2 g-12">
        <section class="box"><div class="box-head"><h3>${L('Vista previa de portada', 'Cover preview')}</h3></div><div class="box-body"><div class="sheet"><span class="stamp">${appr ? L('APROBADO', 'APPROVED') : L('BORRADOR', 'DRAFT')}</span><img class="lg" src="assets/logo-white.png" alt="Omnicon">
          <div style="display:flex;flex-direction:column;gap:10px"><span class="small" style="color:var(--cyan);letter-spacing:.08em">OPERATIONAL RISK ASSESSMENT</span><h3>${h(tx(a.cfg.plant) || L('Instalación', 'Facility'))}</h3>${cover ? `<img class="ph-cov" src="${C.photoURL(cover)}" alt="">` : ''}</div>
          <div class="meta"><span>${h(tx(a.cfg.client))}</span><span>${L('Modalidad', 'Modality')} ${h(C.modName(C.mod(a)))} · ${h(C.modDur(C.mod(a)))}</span><span>${C.fmtDate(new Date().toISOString())} · ${L('versión', 'version')} ${a.reportVersion}</span><span>${L('DEMO · datos ilustrativos', 'DEMO · illustrative data')}</span></div></div></div></section>
        <section class="box"><div class="box-head"><h3>${L('Limitaciones que se declararán', 'Limitations to be declared')}</h3><span class="small mut">${lim.length}</span></div><div class="box-body">${lim.length ? `<ul style="margin:0;padding-left:18px;display:flex;flex-direction:column;gap:4px" class="small">${lim.map(x => `<li>${h(x)}</li>`).join('')}</ul>` : `<p class="small mut">${L('Sin limitaciones registradas.', 'No limitations recorded.')}</p>`}</div></section></div>
      <section class="box"><div class="box-head"><h3>${L('Hoja de ruta de mitigación', 'Mitigation roadmap')}</h3><p>${L('Entregable base en todas las modalidades. Horizonte orientativo; no implica ingeniería de detalle ni compromiso de implementación.', 'Core deliverable in every modality. Indicative horizon; no detailed engineering or implementation commitment.')}</p></div><div class="rm-wrap"><table class="rm"><thead><tr><th>ID</th><th>${L('Acción', 'Action')}</th><th>${L('Escenarios', 'Scenarios')}</th><th>${L('Horizonte', 'Horizon')}</th><th>${L('Responsable sugerido', 'Suggested owner')}</th><th>${L('Prioridad', 'Priority')}</th><th>${L('Estado', 'Status')}</th></tr></thead><tbody>${roadmap || `<tr><td colspan="7" class="mut">${L('Sin acciones.', 'No actions.')}</td></tr>`}</tbody></table></div></section>
      <div class="row"><button class="btn ghost" data-act="nav" data-view="dash">${ic('radar')}${L('Abrir Risk Intelligence', 'Open Risk Intelligence')}</button></div>`;
  };

  U.radarSVG = function (radar, W) {
    W = W || 420; const cx = W / 2, cy = 190, R = 128, n = radar.length;
    const pt = (i, v) => { const ang = -Math.PI / 2 + i * 2 * Math.PI / n; return [cx + Math.cos(ang) * R * v, cy + Math.sin(ang) * R * v]; };
    let g = '';
    [.25, .5, .75, 1].forEach(r => { g += `<polygon points="${radar.map((_, i) => pt(i, r).join(',')).join(' ')}" fill="none" stroke="var(--grid)" stroke-width="1"/>`; });
    [25, 50, 75, 100].forEach(v => { const p = pt(0, v / 100); g += `<text x="${p[0] + 4}" y="${p[1] + 4}" font-size="9.5">${v}</text>`; });
    radar.forEach((d, i) => { const p = pt(i, 1); g += `<line x1="${cx}" y1="${cy}" x2="${p[0]}" y2="${p[1]}" stroke="var(--grid)" ${d.idx == null ? 'stroke-dasharray="4 4"' : ''}/>`; });
    const pts = radar.map((d, i) => d.idx == null ? null : pt(i, d.idx / 100)); const avail = pts.filter(Boolean);
    if (avail.length >= 3) g += `<polygon points="${avail.map(p => p.join(',')).join(' ')}" fill="var(--chart-1)" fill-opacity=".18" stroke="var(--chart-1)" stroke-width="2"/>`;
    pts.forEach(p => { if (p) g += `<circle cx="${p[0]}" cy="${p[1]}" r="4.5" fill="var(--chart-1)" stroke="var(--surface)" stroke-width="2"/>`; });
    radar.forEach((d, i) => {
      const p = pt(i, 1.2); const anchor = Math.abs(p[0] - cx) < 10 ? 'middle' : p[0] > cx ? 'start' : 'end';
      const words = String(tx(d.dim)).split(' '); let l1 = '', l2 = ''; words.forEach(w => { if (!l2 && (l1 + ' ' + w).trim().length <= 16) l1 = (l1 + ' ' + w).trim(); else l2 = (l2 + ' ' + w).trim(); });
      const up = p[1] < cy - 10, y0 = l2 ? (up ? p[1] - 17 : p[1] - 4) : p[1] - 4;
      g += `<text x="${p[0]}" y="${y0}" text-anchor="${anchor}" class="lbl-strong" font-size="11.5">${h(l1)}${l2 ? `<tspan x="${p[0]}" dy="13">${h(l2)}</tspan>` : ''}</text><text x="${p[0]}" y="${y0 + (l2 ? 13 : 0) + 15}" text-anchor="${anchor}" font-size="10.5">${d.idx == null ? L('sin datos', 'no data') : d.idx + ' · ' + d.yes + '/' + d.n + L(' controles', ' controls')}${d.unk ? ' · ' + d.unk + L(' desc.', ' unk.') : ''}</text>`;
    });
    return `<svg viewBox="-80 -10 ${W + 160} 410" role="img" aria-label="${L('Radar de índice relativo de control por dimensión', 'Relative control index radar by dimension')}">${g}</svg>`;
  };
  U.barsSVG = function (rows) {
    const W = 620, rh = 40, top = 10, left = 200, maxV = Math.max(1, ...rows.map(r => r.Alto + r.Medio + r.Bajo + r.Pendiente));
    const sc = (W - left - 40) / maxV; let g = '';
    for (let t = 0; t <= maxV; t++) { const x = left + t * sc; g += `<line x1="${x}" y1="${top - 4}" x2="${x}" y2="${top + rows.length * rh}" stroke="var(--grid)"/><text x="${x}" y="${top + rows.length * rh + 14}" text-anchor="middle" font-size="10">${t}</text>`; }
    const col = { Alto: 'var(--lv-high)', Medio: 'var(--lv-med)', Bajo: 'var(--lv-low)', Pendiente: 'var(--lv-pend)' };
    rows.forEach((r, i) => {
      const y = top + i * rh + 8; let x = left; const nm = r.name.length > 26 ? r.name.slice(0, 25) + '…' : r.name;
      g += `<text x="${left - 10}" y="${y + 15}" text-anchor="end" class="lbl-strong" font-size="11.5">${h(nm)}</text>`;
      ['Alto', 'Medio', 'Bajo', 'Pendiente'].forEach(k => { if (r[k]) { const w = r[k] * sc; g += `<rect x="${x}" y="${y}" width="${w - 2}" height="22" rx="3" fill="${col[k]}" ${k === 'Pendiente' ? 'fill-opacity=".45"' : ''}/><text x="${x + w / 2 - 1}" y="${y + 15}" text-anchor="middle" font-size="11" style="fill:var(--surface);font-weight:600">${r[k]}</text>`; x += w; } });
      if (!(r.Alto + r.Medio + r.Bajo + r.Pendiente)) g += `<text x="${left + 6}" y="${y + 15}" font-size="11">${L('Sin escenarios: no evaluado (no equivale a bajo)', 'No scenarios: not assessed (not the same as low)')}</text>`;
    });
    return `<svg viewBox="0 0 ${W} ${top + rows.length * rh + 22}" role="img" aria-label="${L('Escenarios por proceso y nivel', 'Scenarios by process and level')}">${g}</svg>`;
  };

  U.views.dash = function (a) {
    const f = C.S.ui.flt || (C.S.ui.flt = {});
    const m = C.metrics(a, f); const cell = C.S.ui.cell || null;
    let list = m.scn;
    if (cell === 'pend') list = list.filter(s => !C.LEVEL(s.C, s.P)); else if (cell) { const [c, p] = cell.split(',').map(Number); list = list.filter(s => s.C === c && s.P === p); }
    const kpi = (lbl, v, den, d, act) => `<button class="kpi" data-act="${act || 'noop'}"><small>${lbl}</small><span class="v">${v}${den != null ? `<em> / ${den}</em>` : ''}</span><span class="d">${d}</span></button>`;
    const sel = (k, lbl, opts) => `<div class="field"><label for="fl-${k}">${lbl}</label><select id="fl-${k}" data-flt="${k}">${U.opt('', L('Todos', 'All'), f[k] || '')}${opts.map(([v, l]) => U.opt(v, l, f[k] || '')).join('')}</select></div>`;
    const spof = C.sharedControllers(a);
    const scnItems = list.map(s => `<button class="scn-item" data-act="scn-open" data-id="${s.id}"><span class="pill pri">${s.id}</span><span><b>${h(tx(s.title))}</b><span>${h(C.procName(a, s.proc))} · ${L('confianza', 'confidence')} ${h(tx(s.conf).toLowerCase())} · ${s.controls.filter(c => c.st === 'Verificado').length}/${s.controls.length} ${L('controles verificados', 'controls verified')} · ${a.photos.filter(p => p.links && (p.links.scenario === s.id || s.findings.includes(p.links.finding))).length} ${L('evidencias', 'evidence items')}</span></span>${U.lv(C.LEVEL(s.C, s.P))}</button>`).join('');
    const pct = (n, d) => d ? Math.round(n / d * 100) + ' %' : L('sin datos', 'no data');
    const mod = C.mod(a);
    return `<section class="dash-hero"><div style="display:flex;flex-direction:column;gap:8px"><span class="eyebrow">Risk Intelligence · ${h(a.code)}</span><h1>${h(tx(a.cfg.plant) || 'Assessment')}</h1>
        <p>${h(tx(a.cfg.client))} · ${L('Modalidad', 'Modality')} ${h(C.modName(mod))} (${h(C.modDur(mod))}) · ${m.inc.length} ${L('procesos críticos seleccionados.', 'selected critical processes.')} ${a.cfg.modality === 'light' ? L('Los resultados no representan una evaluación integral de la planta.', 'Results do not represent a whole-plant assessment.') : ''} ${L('Corte', 'As of')}: ${C.fmtDate(a.updated, true)}.</p></div>
        <div class="row"><span class="pill demo" style="background:rgba(255,244,224,.12);color:#ffd28a;border-color:#ffd28a">${L('DEMO · datos ilustrativos', 'DEMO · illustrative data')}</span><button class="btn primary sm" data-act="go" data-stage="7" data-target="">${ic('doc', 'sm')}${L('Informe PDF', 'PDF report')}</button></div></section>
      <section class="box"><div class="box-body"><div class="filters">
        ${sel('proc', L('Proceso', 'Process'), m.inc.map(p => [p.key, tx(p.name)]))}${sel('area', L('Área', 'Area'), a.areas.map(x => [x.id, tx(x.name)]))}${sel('level', L('Nivel de riesgo', 'Risk level'), ['Alto', 'Medio', 'Bajo', 'Pendiente'].map(x => [x, tx(x)]))}${sel('dim', L('Dimensión', 'Dimension'), D.DIMS.map(x => [x, tx(x)]))}${sel('conf', L('Confianza', 'Confidence'), ['Verificado', 'Estimado', 'Desconocido'].map(x => [x, tx(x)]))}${sel('state', L('Estado', 'Status'), [['Evaluado', tx('Evaluado')], ['Pendiente', L('Pendiente de evaluación', 'Pending assessment')]])}
        <button class="btn ghost sm" data-act="flt-clear" style="align-self:flex-end">${L('Limpiar', 'Clear')}</button></div></div></section>
      <div class="kpis">
        ${kpi(L('Procesos evaluados', 'Processes assessed'), m.procEval.length, m.procs.length, L('Con ≥1 escenario clasificado / procesos incluidos', 'With ≥1 rated scenario / processes included'), 'k-proc')}
        ${kpi(L('Escenarios identificados', 'Scenarios identified'), m.scn.length, null, `${tx('Alto')} ${m.lv.Alto} · ${tx('Medio')} ${m.lv.Medio} · ${tx('Bajo')} ${m.lv.Bajo} · ${tx('Pendiente')} ${m.lv.Pendiente}`, 'k-scn')}
        ${kpi(L('Controles verificados', 'Controls verified'), m.ctlVer, m.ctlTotal, pct(m.ctlVer, m.ctlTotal) + L(' de los controles registrados en escenarios', ' of controls recorded in scenarios'), 'k-scn')}
        ${kpi(L('Cobertura de evidencia', 'Evidence coverage'), m.reqOk, m.reqTotal, L(`${m.photos} fotos · ${m.reqJust} por revisar · ${m.reqNone} sin foto`, `${m.photos} photos · ${m.reqJust} to review · ${m.reqNone} no photo`), 'k-ev')}
        ${kpi(L('Preguntas respondidas', 'Questions answered'), m.appDone, m.appTotal, L(`${m.unknown} desconocidas (brechas, no riesgo)`, `${m.unknown} unknown (gaps, not risk)`), 'k-q')}
        ${kpi(L('Riesgos altos', 'High risks'), m.lv.Alto, m.scn.length, L('Escenarios clasificados como alto / escenarios', 'Scenarios rated high / scenarios'), 'k-high')}
        ${kpi(L('Recomendaciones', 'Recommendations'), m.recs.length, null, L(`${m.recHigh} prioridad alta · ${m.recDone}/${m.recs.length} completadas`, `${m.recHigh} high priority · ${m.recDone}/${m.recs.length} completed`), 'k-rec')}
        ${kpi(L('Avance del assessment', 'Assessment progress'), m.ev.done, m.ev.total, L('Criterios de completitud cumplidos', 'Completeness criteria met'), 'k-wiz')}
      </div>
      <div class="dgrid">
        <section class="box span-5"><div class="box-head"><h3>${L('Matriz de riesgos 3×3', '3×3 risk matrix')}</h3><p>${L('Seleccione una celda para ver sus escenarios.', 'Select a cell to see its scenarios.')}</p></div><div class="box-body">${U.matrix(a, m.scn, cell, 'mx-dash')}<p class="def">${L('Escala ordinal propuesta (no aprobada). Las categorías no representan probabilidades porcentuales.', 'Proposed ordinal scale (not approved). Categories do not represent percentage probabilities.')}</p></div></section>
        <section class="box span-7"><div class="box-head"><h3>${L('Radar de dimensiones de control', 'Control dimensions radar')}</h3><p>${L('Índice relativo de control (0–100) por dimensión.', 'Relative control index (0–100) per dimension.')}</p></div><div class="box-body chart">${U.radarSVG(m.radar)}
          <p class="def"><b>${L('Definición', 'Definition')}:</b> ${L('índice = respuestas «Sí» ÷ (respuestas «Sí» + «No») × 100, solo en preguntas cuyo «Sí» indica un control presente. «Desconocido» y «No aplica» no puntúan y se reportan aparte. Con menos de 2 respuestas el eje muestra «sin datos», no cero. No es una probabilidad.', 'index = “Yes” answers ÷ (“Yes” + “No” answers) × 100, only for questions where “Yes” means a control is present. “Unknown” and “Not applicable” are not scored and are reported separately. With fewer than 2 answers the axis shows “no data”, not zero. It is not a probability.')}</p></div></section>
        <section class="box span-7"><div class="box-head"><h3>${L('Escenarios por proceso y nivel', 'Scenarios by process and level')}</h3><div class="legend"><span><i style="background:var(--lv-high)"></i>${tx('Alto')}</span><span><i style="background:var(--lv-med)"></i>${tx('Medio')}</span><span><i style="background:var(--lv-low)"></i>${tx('Bajo')}</span><span><i style="background:var(--lv-pend);opacity:.5"></i>${tx('Pendiente')}</span></div></div><div class="box-body chart">${m.byProc.length ? U.barsSVG(m.byProc.filter(r => !f.proc || r.key === f.proc)) : `<div class="empty">${L('Sin procesos incluidos.', 'No processes included.')}</div>`}</div></section>
        <section class="box span-5"><div class="box-head"><h3>${L('Calidad y cobertura', 'Quality and coverage')}</h3></div><div class="box-body" style="gap:10px">
          <div class="toc"><span>${L('Procesos fuera de alcance', 'Processes out of scope')}</span><span>${m.outScope}</span><span>${L('Procesos «No aplica» (justificados)', '“Not applicable” processes (justified)')}</span><span>${m.na}</span><span>${L('Procesos con estado desconocido', 'Processes with unknown status')}</span><span>${m.unkProc}</span><span>${L('Respuestas desconocidas', 'Unknown answers')}</span><span>${m.unknown}</span><span>${L('Excepciones fotográficas', 'Photo exceptions')}</span><span>${m.reqJust} ${L('por revisar', 'to review')}</span></div>
          ${spof.map(x => `<div class="alert-spof">${ic('branch')}<div><b>${L('Candidato a punto único de falla', 'Single point of failure candidate')}: ${h(x.plc.tag)}</b><p class="small">${L('Controla', 'Controls')} ${h(x.pumps.map(p => p.tag).join(L(' y ', ' and ')))}. ${L('Ver escenarios vinculados y la vista de dependencias.', 'See linked scenarios and the dependency view.')}</p><button class="btn ghost sm" data-act="nav" data-view="journey" style="margin-top:6px">${ic('map', 'sm')}${L('Ver en Risk Journey', 'View in Risk Journey')}</button></div></div>`).join('')}</div></section>
        <section class="box span-12" id="dash-scn"><div class="box-head"><h3>${L('Escenarios', 'Scenarios')} ${cell ? (cell === 'pend' ? L('· pendientes de evaluación', '· pending assessment') : '· C' + cell.split(',')[0] + ' P' + cell.split(',')[1]) : ''}</h3>${cell ? `<button class="btn ghost sm" data-act="cell" data-cell="">${L('Quitar selección', 'Clear selection')}</button>` : ''}<p>${L('Abra un escenario para ver justificación, controles, evidencia fotográfica y recomendación.', 'Open a scenario to see justification, controls, photo evidence and recommendation.')}</p></div><div class="scn-list">${scnItems || `<div class="box-body"><div class="empty">${L('Sin escenarios para estos filtros.', 'No scenarios for these filters.')}</div></div>`}</div></section>
      </div>`;
  };

  U.views.journey = function (a) {
    const mode = C.S.ui.jm || 'risk'; const selId = C.S.ui.jsel;
    const inc = new Set(C.included(a).map(p => p.key));
    const zones = a.areas.filter(ar => !C.isOut(ar)).map(ar => ({ ar, items: a.assets.filter(x => x.area === ar.id && !C.isOut(x)) }));
    const out = a.processes.filter(p => p.status === 'fuera' || p.status === 'desconocido');
    const NW = 150, NH = 62, PAD = 18, HD = 56, cut = (t, n) => { t = String(t || ''); return t.length > n ? t.slice(0, n - 1) + '…' : t; }, ZW = 2 * NW + 3 * PAD;
    const pos = {}; const zsvg = []; const COLS = 2; let rowY = 20, rowH = 0;
    zones.forEach((z, zi) => {
      const col = zi % COLS; if (col === 0 && zi) { rowY += rowH + 26; rowH = 0; }
      const zx = 20 + col * (ZW + 26); const rows = Math.max(1, Math.ceil(z.items.length / 2)); const zh = HD + 6 + rows * (NH + PAD) + 4; rowH = Math.max(rowH, zh);
      z.items.forEach((x, i) => { pos[x.id] = { x: zx + PAD + (i % 2) * (NW + PAD), y: rowY + HD + Math.floor(i / 2) * (NH + PAD) }; });
      zsvg.push({ x: zx, y: rowY, w: ZW, h: zh, z });
    });
    const maxH = rowY + rowH - 20;
    const W = 20 + Math.min(COLS, Math.max(1, zones.length)) * (ZW + 26) + 10, H = 40 + maxH + 86;
    const riskOf = id => { const ls = a.scenarios.filter(s => s.assets.includes(id)).map(s => C.LEVEL(s.C, s.P) || 'Pendiente'); return ls.includes('Alto') ? 'Alto' : ls.includes('Medio') ? 'Medio' : ls.includes('Pendiente') ? 'Pendiente' : ls.includes('Bajo') ? 'Bajo' : null; };
    const spof = new Set(C.sharedControllers(a).map(x => x.plc.id)); const reqs = C.photoReqs(a);
    let g = `<defs><pattern id="hatch" width="8" height="8" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><line x1="0" y1="0" x2="0" y2="8" stroke="var(--line)" stroke-width="3"/></pattern><marker id="arw" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="var(--muted)"/></marker></defs>`;
    zsvg.forEach(z => { g += `<rect x="${z.x}" y="${z.y}" width="${z.w}" height="${z.h}" rx="14" fill="var(--surface-2)" stroke="var(--line)"/><g><title>${h(tx(z.z.ar.name))} · ${h(C.procName(a, z.z.ar.proc))}</title><text x="${z.x + 14}" y="${z.y + 22}" font-size="12.5" font-weight="600" fill="var(--ink)">${h(cut(tx(z.z.ar.name), 42))}</text><text x="${z.x + 14}" y="${z.y + 39}" font-size="10.5" fill="var(--muted)">${h(cut(C.procName(a, z.z.ar.proc), 52))}</text></g>`; });
    a.deps.forEach(d => {
      const p1 = pos[d.from], p2 = pos[d.to]; if (!p1 || !p2) return;
      const hl = mode === 'deps' && (spof.has(d.to) || spof.has(d.from)) && d.type === 'Control';
      const x1 = p1.x + NW / 2, y1 = p1.y + NH / 2, x2 = p2.x + NW / 2, y2 = p2.y + NH / 2, mx = (x1 + x2) / 2;
      g += `<path d="M${x1} ${y1} C ${mx} ${y1}, ${mx} ${y2}, ${x2} ${y2}" fill="none" stroke="${hl ? 'var(--approval)' : 'var(--muted)'}" stroke-opacity="${mode === 'deps' ? (hl ? 1 : .35) : .5}" stroke-width="${hl ? 3 : 1.5}" ${d.type === 'Control' ? 'stroke-dasharray="6 4"' : ''} marker-end="url(#arw)"/>`;
    });
    a.assets.forEach(x => {
      const p = pos[x.id]; if (!p) return;
      const r = riskOf(x.id); const evald = C.assetProcs(x).some(k => inc.has(k)) && r; const rq = reqs.find(q => q.key === 'asset:' + x.id);
      let fill = 'var(--surface)', stroke = 'var(--line)', sub = tx(x.type);
      if (mode === 'risk') { if (r === 'Alto') { fill = 'var(--lv-high-bg)'; stroke = 'var(--lv-high)'; } else if (r === 'Medio') { fill = 'var(--lv-med-bg)'; stroke = 'var(--lv-med)'; } else if (r === 'Bajo') { fill = 'var(--lv-low-bg)'; stroke = 'var(--lv-low)'; } else if (r === 'Pendiente') { fill = 'var(--lv-pend-bg)'; stroke = 'var(--lv-pend)'; } sub = r ? C.lvlText(r === 'Pendiente' ? null : r) : L('Sin escenarios', 'No scenarios'); }
      if (mode === 'deps') { if (spof.has(x.id)) { fill = 'var(--approval-soft)'; stroke = 'var(--approval)'; sub = L('Dependencia común', 'Common dependency'); } else sub = a.deps.filter(d => d.from === x.id).length + L(' dependencias', ' dependencies'); }
      if (mode === 'cov') { sub = rq ? C.PH_LBL[rq.status] : L('Foto opcional', 'Photo optional'); if (rq && rq.status === 'capturada') stroke = 'var(--ok-ink)'; else if (rq && rq.status === 'sin foto') stroke = 'var(--err-ink)'; }
      const hatch = !evald && mode === 'risk';
      g += `<g class="jnode ${selId === x.id ? 'sel' : ''}" tabindex="0" role="button" aria-label="${h(x.tag)}: ${h(sub)}" data-act="j-node" data-id="${x.id}">
        <rect class="nb" x="${p.x}" y="${p.y}" width="${NW}" height="${NH}" rx="10" fill="${fill}" stroke="${stroke}" stroke-width="2"/>${hatch ? `<rect x="${p.x}" y="${p.y}" width="${NW}" height="${NH}" rx="10" fill="url(#hatch)" opacity=".5"/>` : ''}
        <title>${h(x.tag)} · ${h(tx(x.name))} · ${h(sub)}</title><text x="${p.x + 12}" y="${p.y + 25}" font-size="13" font-weight="600" fill="var(--ink)">${h(cut(x.tag, 16))}</text><text x="${p.x + 12}" y="${p.y + 44}" font-size="10.5" fill="var(--muted)">${h(cut(sub, 24))}</text></g>`;
    });
    const oy = 40 + maxH + 12;
    const stL = s => s === 'fuera' ? L('fuera de alcance', 'out of scope') : L('desconocido', 'unknown');
    { const full = L('Fuera de la evaluación', 'Not assessed') + ': ' + (out.map(p => tx(p.name) + ' (' + stL(p.status) + ')').join(' · ') || L('ninguno', 'none')); const per = Math.max(40, Math.floor((W - 40) / 6.2)); const lines = []; let cur = '';
      full.split(' ').forEach(w => { if ((cur + ' ' + w).trim().length > per) { lines.push(cur.trim()); cur = w; } else cur += ' ' + w; }); if (cur.trim()) lines.push(cur.trim());
      g += lines.slice(0, 3).map((l, i) => `<text x="20" y="${oy + 14 + i * 16}" font-size="11.5" fill="var(--muted)">${h(l)}</text>`).join(''); }
    const s = selId ? C.asset(a, selId) : null;
    let panel = `<div class="box-body"><div class="empty">${ic('map')}<b>${L('Seleccione un activo', 'Select an asset')}</b><span>${L('Verá sus riesgos, dependencias, controles, evidencias y recomendaciones.', 'You will see its risks, dependencies, controls, evidence and recommendations.')}</span></div></div>`;
    if (s) {
      const scn = a.scenarios.filter(x => x.assets.includes(s.id)); const deps = a.deps.filter(d => d.from === s.id || d.to === s.id);
      const ph = a.photos.filter(p => p.links && p.links.asset === s.id); const rq = reqs.find(q => q.key === 'asset:' + s.id);
      panel = `<div class="box-body"><div><span class="pill">${h(tx(s.type))}</span><h3 style="font-size:18px;font-weight:600;margin-top:6px">${h(s.tag)} · ${h(tx(s.name))}</h3><p class="small mut">${h(C.areaName(a, s.area))} · ${h(C.procName(a, s.proc))} · ${h(tx(s.ver))}</p></div>
        <div class="sec-title">${L('Escenarios', 'Scenarios')}</div>${scn.map(x => `<button class="scn-item" style="padding:8px 0" data-act="scn-open" data-id="${x.id}"><span class="pill pri">${x.id}</span><span><b>${h(tx(x.title))}</b></span>${U.lv(C.LEVEL(x.C, x.P))}</button>`).join('') || `<p class="small mut">${L('Sin escenarios vinculados: no evaluado, no equivale a riesgo bajo.', 'No linked scenarios: not assessed, not the same as low risk.')}</p>`}
        <div class="sec-title">${L('Dependencias', 'Dependencies')}</div>${deps.map(d => `<p class="small">${h(C.assetLbl(a, d.from))} → ${h(C.assetLbl(a, d.to))} <span class="mut">(${h(tx(d.type))})</span></p>`).join('') || `<p class="small mut">${L('Sin dependencias registradas.', 'No dependencies recorded.')}</p>`}
        <div class="sec-title">${L('Evidencia', 'Evidence')}</div><div class="row">${ph.map(p => `<button data-act="lightbox" data-id="${p.id}" style="width:88px;height:66px;border-radius:8px;overflow:hidden;border:1px solid var(--line)"><img src="${C.photoURL(p)}" alt="${h(tx(p.title))}" style="width:100%;height:100%;object-fit:cover"></button>`).join('')}${rq && rq.status !== 'capturada' ? U.phState(rq.status) : ''}${!ph.length && !rq ? `<span class="small mut">${L('Sin fotos.', 'No photos.')}</span>` : ''}</div></div>`;
    }
    return `<div class="hello"><div><h1>Risk Journey</h1><p>${L('Modelo ilustrativo 2D generado a partir de las áreas, activos y dependencias registrados. No es un gemelo digital ni una representación validada de la instalación.', 'Illustrative 2D model generated from the recorded areas, assets and dependencies. It is not a digital twin or a validated representation of the facility.')}</p></div>
      <div class="seg" role="group" aria-label="${L('Capa', 'Layer')}">${[['risk', L('Riesgo', 'Risk')], ['deps', L('Dependencias', 'Dependencies')], ['cov', L('Cobertura de evidencia', 'Evidence coverage')]].map(([k, l]) => `<button data-act="j-mode" data-m="${k}" aria-pressed="${mode === k}">${l}</button>`).join('')}</div></div>
      <div class="journey"><section class="box"><div class="box-body jcanvas"><div class="scroll-x"><svg viewBox="0 0 ${W} ${H}" style="min-width:${Math.min(W, 640)}px" role="group" aria-label="${L('Mapa ilustrativo de la instalación', 'Illustrative facility map')}">${g}</svg></div>
        <div class="legend">${mode === 'risk' ? `<span><i style="background:var(--lv-high)"></i>${C.lvlText('Alto')}</span><span><i style="background:var(--lv-med)"></i>${tx('Medio')}</span><span><i style="background:var(--lv-low)"></i>${tx('Bajo')}</span><span><i style="background:var(--lv-pend)"></i>${tx('Pendiente')}</span><span><i style="background:var(--line)"></i>${L('Rayado: sin escenarios (no evaluado)', 'Hatched: no scenarios (not assessed)')}</span>` : mode === 'deps' ? `<span><i style="background:var(--approval)"></i>${L('Dependencia de control común', 'Common control dependency')}</span><span>${L('Línea discontinua: control · continua: energía, comunicación, señal', 'Dashed: control · solid: power, communication, signal')}</span>` : `<span><i style="background:var(--ok-ink)"></i>${C.PH_LBL['capturada']}</span><span><i style="background:var(--err-ink)"></i>${C.PH_LBL['sin foto']}</span>`}</div>
        <p class="def">${L('El color de cada activo indica el nivel del peor escenario que lo involucra; la criticidad del proceso se muestra aparte. Un riesgo puede abarcar varios activos y áreas.', 'Each asset’s color shows the level of the worst scenario involving it; process criticality is shown separately. A risk can span several assets and areas.')}</p></div></section>
      <section class="box">${panel}</section></div>`;
  };

  U.views.config = function (a) {
    const t = C.S.ui.ctab || 'lib'; const lib = C.S.lib;
    const tabs = [['lib', L('Biblioteca de preguntas', 'Question library')], ['mod', L('Modalidades', 'Modalities')], ['tpl', L('Catálogo industrial', 'Industry catalog')], ['types', L('Tipos y categorías OT', 'Types & OT categories')], ['photo', L('Cobertura fotográfica', 'Photo coverage')]].map(([k, l]) => `<button role="tab" data-act="ctab" data-t="${k}" aria-selected="${t === k}">${l}</button>`).join('');
    let body = '';
    if (t === 'lib') {
      const fi = C.S.ui.cind || 'oilgas'; const qs = lib.questions.filter(q => fi === 'all' || q.ind.includes('*') || q.ind.includes(fi)).sort((x, y) => (x.cond ? 1 : 0) - (y.cond ? 1 : 0) || x.order - y.order);
      body = `<div class="row" style="justify-content:space-between"><div class="field" style="min-width:220px"><label for="cind">${L('Industria', 'Industry')}</label><select id="cind" data-cfgui="cind">${U.opt('all', L('Todas', 'All'), fi)}${D.INDUSTRIES.map(i => U.opt(i.key, tx(i.name), fi)).join('')}</select></div><button class="btn primary" data-act="q-new" style="align-self:flex-end">${ic('plus')}${L('Nueva pregunta', 'New question')}</button></div>
        <section class="box"><div class="scroll-x"><table style="min-width:960px"><thead><tr><th>ID</th><th>${L('Pregunta', 'Question')}</th><th>${L('Dimensión', 'Dimension')}</th><th>${L('Industrias', 'Industries')}</th><th>${L('Modalidades', 'Modalities')}</th><th>${L('Orden', 'Order')}</th><th>${L('Condición', 'Condition')}</th><th>${L('Activa', 'Active')}</th><th></th></tr></thead><tbody>
        ${qs.map(q => `<tr class="${q.active ? '' : 'qrow-off'}"><td><b>${q.id}</b><div class="small mut">v${q.v}</div></td><td style="max-width:380px">${h(tx(q.text))}${q.req ? '' : ` <span class="pill">${L('Complementaria', 'Supplementary')}</span>`}</td><td>${h(tx(q.dim))}</td><td>${q.ind.map(i => i === '*' ? L('Común', 'Common') : C.indName(i)).join(', ')}</td><td>${q.mods.map(m => C.modName(lib.modalities[m])).join(', ')}</td><td>${q.cond ? '—' : q.order}</td><td class="small">${q.cond ? (q.cond.q ? h(q.cond.q + ' ∈ ' + q.cond.in.map(tx).join('/')) : '') + (q.cond.shared ? L(' o PLC común', ' or shared PLC') : '') : L('Núcleo', 'Core')}</td>
          <td><button class="tog" role="switch" aria-checked="${q.active}" aria-label="${q.id}" data-act="q-toggle" data-id="${q.id}"></button></td><td><button class="icon-btn" data-act="q-edit" data-id="${q.id}" aria-label="${L('Editar', 'Edit')} ${q.id}">${ic('edit', 'sm')}</button></td></tr>`).join('')}</tbody></table></div></section>`;
    } else if (t === 'mod') {
      body = `<div class="mods">${Object.values(lib.modalities).map(m => `<div class="mod"><b>${h(C.modName(m))}</b><span class="t">${h(C.modDur(m))}</span><p class="small mut">${h(tx(m.desc))}</p><div class="field"><label for="mc-${m.key}">${L('Núcleo de preguntas (demostrativo)', 'Core questions (demo)')}</label><input id="mc-${m.key}" type="number" min="1" max="60" data-lib="mod.${m.key}.count" value="${m.count}"></div></div>`).join('')}</div>
        <div class="note-demo">${ic('info')}<span>${L('Los valores 10 / 20 / configurable son parámetros de demostración. No son mínimos ni máximos contractuales ni indicadores de precisión. Las ramificaciones condicionales se agregan según contexto en cualquier modalidad.', 'The 10 / 20 / configurable values are demo parameters. They are not contractual minimums or maximums nor precision indicators. Conditional branches are added by context in any modality.')}</span></div>`;
    } else if (t === 'tpl') {
      body = U.catalogTab();
    } else if (t === 'types') {
      body = U.typesTab();
    } else {
      const R = lib.photoRules;
      body = `<section class="box"><div class="box-body"><div class="grid3"><div class="field"><label for="pr-area">${L('Fotos sugeridas por área en alcance', 'Suggested photos per in-scope area')}</label><input id="pr-area" type="number" min="0" max="5" data-lib="rule.perArea" value="${R.perArea}"></div><div class="field"><label for="pr-asset">${L('Fotos sugeridas por activo de los tipos seleccionados', 'Suggested photos per asset of selected types')}</label><input id="pr-asset" type="number" min="0" max="5" data-lib="rule.perAsset" value="${R.perAsset}"></div><div class="field"><label for="pr-f">${L('Fotos sugeridas por hallazgo', 'Suggested photos per finding')}</label><input id="pr-f" type="number" min="0" max="5" data-lib="rule.perFinding" value="${R.perFinding}"></div></div>
        <div class="field"><span class="lbl">${L('Tipos de activo que requieren foto', 'Asset types that require a photo')}</span><div class="cbs">${C.assetTypes().map(x => `<label><input type="checkbox" data-act="rule-type" data-v="${h(x)}" ${R.assetTypes.includes(x) ? 'checked' : ''}>${h(tx(x))}</label>`).join('')}</div></div>
        <div class="note-info">${ic('info')}<span>${L('Estas reglas se aplican de inmediato a la guía de cobertura y al progreso. Son sugerencias: la falta de una foto no bloquea el avance ni equivale a riesgo bajo.', 'These rules apply immediately to the coverage guide and progress. They are suggestions: a missing photo does not block progress nor mean low risk.')}</span></div></div></section>`;
    }
    return `<div class="hello"><div><h1>${L('Biblioteca y plantillas', 'Library & templates')}</h1><p>${L('Configuración desacoplada de la interfaz. Biblioteca vigente:', 'Configuration decoupled from the interface. Current library:')} <b>v${lib.version}</b>. ${a ? L(`El assessment activo usa la v${a.libVersion}; los cambios de preguntas aplican a assessments nuevos y no alteran los existentes.`, `The active assessment uses v${a.libVersion}; question changes apply to new assessments and do not alter existing ones.`) : ''}</p></div></div>
      <div class="tabs" role="tablist">${tabs}</div>${body}`;
  };

  U.aboutBody = function () {
    const W = L('Funciona', 'Works'), Lm = L('Limitado', 'Limited'), Sm = L('Simulado', 'Simulated'), N = L('No implementado', 'Not implemented');
    const rows = [
      [W, L('Wizard de 7 etapas con progreso calculado por criterios (respuestas + evidencia), estados por etapa, «Qué tengo / Qué me falta» y salto al registro exacto.', '7-stage wizard with criteria-based progress (answers + evidence), stage states, “What I have / What’s missing” and jump to the exact record.')],
      [W, L('Creación de assessments desde plantillas; cambio de modalidad recalcula preguntas aplicables; ramificaciones por respuesta, por dependencias registradas y por incertidumbre.', 'Assessments created from templates; changing modality recalculates applicable questions; branches by answer, recorded dependencies and uncertainty.')],
      [W, L('Biblioteca editable (agregar, editar, activar, versionar, ordenar, condicionar). Los assessments existentes conservan su versión.', 'Editable library (add, edit, activate, version, order, condition). Existing assessments keep their version.')],
      [Sm, L('Acceso con usuarios de demostración; sin autenticación real. Colaboración: autor, fecha e historial por registro, sin sincronización entre dispositivos.', 'Sign-in with demo users; no real authentication. Collaboration: author, date and history per record, no sync across devices.')],
      [W, L('Carga de fotos desde archivo o cámara del dispositivo (selector de archivos del navegador), asociación a área, activo, pregunta, hallazgo o escenario, galería y vista ampliada.', 'Photo upload from file or device camera (browser file picker), linking to area, asset, question, finding or scenario, gallery and enlarged view.')],
      [W, L('Pendientes fotográficos no bloqueantes con motivo, estados «sin foto», «justificación por revisar» y «excepción aceptada».', 'Non-blocking photo items with reason; “no photo”, “justification to review” and “exception accepted” states.')],
      [W, L('Risk Intelligence con filtros, matriz 3×3, radar con índice definido, barras y drill-down a evidencia; usa la misma fuente de datos que el wizard y el PDF.', 'Risk Intelligence with filters, 3×3 matrix, defined-index radar, bars and drill-down to evidence; same data source as the wizard and PDF.')],
      [W, L('Generación real de PDF en el navegador (jsPDF), en español o inglés, con portada, gráficos vectoriales, fichas, fotos, hoja de ruta, limitaciones y anexos.', 'Real in-browser PDF generation (jsPDF), in English or Spanish, with cover, vector charts, risk sheets, photos, roadmap, limitations and annexes.')],
      [W, L('Interfaz bilingüe EN/ES. El contenido demo y la biblioteca se traducen; el texto que escribe el usuario se conserva tal como se escribió.', 'Bilingual EN/ES interface. Demo content and library are translated; text typed by users is kept as written.')],
      [Lm, L('Persistencia solo en este navegador: datos en localStorage y fotos en IndexedDB. Otro dispositivo o una ventana privada no verá los datos. Fotos optimizadas a 1600 px.', 'Persistence only in this browser: data in localStorage and photos in IndexedDB. Another device or private window will not see the data. Photos optimized to 1600 px.')],
      [Sm, L('Datos de cliente, instalación, preguntas, fotos y escenarios: ficticios e ilustrativos. Usuarios y roles: no implementados (sin login ni aprobación multiusuario).', 'Client, facility, questions, photos and scenarios: fictitious and illustrative. Users and roles: not implemented (no login or multi-user approval).')],
      [W, L('Inventario OT con procedencia (catálogo, Excel, manual, documento, entrevista, campo) y madurez (Sugerido, Validado, Evaluado); importación de activos y dependencias desde Excel o CSV con mapeo, validación y trazabilidad por fila; catálogo industrial versionado.', 'OT inventory with provenance (catalog, Excel, manual, document, interview, field) and maturity (Suggested, Validated, Assessed); asset and dependency import from Excel or CSV with mapping, validation and per-row traceability; versioned industry catalog.')],
      [W, L('Recorrido guiado (etapa 3) para tablet y móvil: confirmar, descartar, corregir, agregar, evidencia y hallazgo, con notas y documentos vinculados al elemento.', 'Guided walkdown (stage 3) for tablet and mobile: confirm, discard, correct, add, evidence and finding, with notes and documents linked to the item.')],
      [W, L('Risk Journey en Process View y OT Dependency View sobre el mismo modelo, con filtros, detalle del registro único e instantáneas de evolución; trazabilidad por ID desde dashboard, escenarios y PDF (Anexo C) hasta sus fuentes.', 'Risk Journey in Process View and OT Dependency View on the same model, with filters, single-record detail and evolution snapshots; ID traceability from dashboard, scenarios and PDF (Annex C) back to their sources.')],
      [N, L('Fuera del alcance del artefacto: servidor compartido, modo sin conexión, sincronización entre dispositivos, portal cliente, versionado de informes aprobados, 3D, eliminación de metadatos EXIF y control de acceso a fotos.', 'Outside the artifact scope: shared server, offline mode, cross-device sync, client portal, approved report versioning, 3D, EXIF metadata removal and photo access control.')]
    ];
    return `<section class="box"><div class="scroll-x"><table style="min-width:620px"><thead><tr><th>${L('Estado', 'Status')}</th><th>${L('Detalle', 'Detail')}</th></tr></thead><tbody>${rows.map(([s, d]) => `<tr><td><span class="pill ${s === W ? 'ok' : s === Lm ? 'warn' : s === Sm ? 'vio' : ''}">${s}</span></td><td>${h(d)}</td></tr>`).join('')}</tbody></table></div></section>
      <div class="note-info">${ic('info')}<span>${L('Fuente: repositorio omnicon-operational-risk-assesment (especificación funcional v0.1, metodología v0.1 y decisiones del 2026-11-09). Todo lo metodológico está pendiente de validación con especialistas de Omnicon.', 'Source: omnicon-operational-risk-assesment repository (functional spec v0.1, methodology v0.1 and 2026-11-09 decisions). All methodology is pending validation by Omnicon specialists.')}</span></div>`;
  };

  // ---------- Team & history ----------
  U.views.team = function (a) {
    const hist = (a.history || []).map(x => `<div class="hrow">${U.av(x.by, 'sm')}<div><b>${h(C.uname(x.by) || '—')}</b> <span>${h(L(x.es, x.en))}</span><small>${C.fmtDate(x.ts, true)}</small></div></div>`).join('');
    return `<div class="hello"><div><h1>${L('Equipo e historial', 'Team & history')}</h1><p>${L('Quién participa en este assessment y qué ha registrado cada persona.', 'Who takes part in this assessment and what each person has recorded.')}</p></div></div>
      <section class="box"><div class="box-head"><h3>${L('Responsabilidades en este assessment', 'Responsibilities in this assessment')}</h3><p>${L('El responsable es una asignación de este assessment; el rol global de cada persona no cambia.', 'The lead is an assignment for this assessment; each person’s global role does not change.')}</p></div><div class="box-body">${U.people(a)}</div></section>
      <div class="note-demo">${ic('info')}<span>${L('Colaboración simulada: cada registro guarda autor y fecha, y puede cambiar de usuario para ver el trabajo de otro integrante. La edición simultánea real, la sincronización y la prevención de sobrescrituras requieren un servidor compartido y quedan fuera del alcance del artefacto.', 'Simulated collaboration: each record stores author and date, and you can switch user to see another member’s work. Real simultaneous editing, sync and overwrite prevention need a shared server and are outside the artifact scope.')}</span></div>
      <section class="box"><div class="box-head"><h3>${L('Historial de cambios', 'Change history')}</h3><span class="small mut">${(a.history || []).length}</span></div><div class="hist">${hist || `<div class="box-body"><div class="empty">${L('Sin actividad registrada.', 'No activity recorded.')}</div></div>`}</div></section>`;
  };

  // ---------- Settings ----------
  U.views.settings = function () {
    const admin = C.isAdmin(); const P = C.S.perms; const th = document.documentElement.dataset.theme || 'system';
    const perm = (k, l, d) => `<div class="prow"><div><b>${l}</b><span>${d}</span></div><button class="tog" role="switch" aria-checked="${!!P[k]}" aria-label="${l}" data-act="perm" data-p="${k}" ${admin ? '' : 'disabled'}></button></div>`;
    const users = C.USERS.map(u => { const lead = C.S.assessments.filter(a => a.leadId === u.id).length, team = C.S.assessments.filter(a => (a.team || []).includes(u.id)).length;
      return `<tr><td><span class="row" style="gap:10px;flex-wrap:nowrap">${U.av(u.id, 'sm')}<b>${h(u.name)}</b></span></td><td><span class="pill ${u.role === 'admin' ? 'nv' : 'pri'}">${C.roleName(u)}</span></td><td>${lead}</td><td>${team}</td></tr>`; }).join('');
    const li = arr => `<ul class="plain">${arr.map(x => `<li>${x}</li>`).join('')}</ul>`;
    const mrow = (s, cls, items) => items.map(t => `<tr><td><span class="pill ${cls}">${s}</span></td><td>${t}</td></tr>`).join('');
    const matrix = `<div class="scroll-x"><table style="min-width:560px"><tbody>
      ${mrow(L('Conservado', 'Kept'), 'ok', [L('Metodología, 7 etapas, reglas de completitud, cuestionario adaptativo, matriz 3×3, radar e índices, hoja de ruta.', 'Methodology, 7 stages, completeness rules, adaptive questionnaire, 3×3 matrix, radar and indexes, roadmap.'), L('Cuatro plantillas (Oil & Gas, Cemento, Minería, Energía), tres modalidades, biblioteca versionada, estados Incluido / Fuera del alcance / No aplica / Desconocido.', 'Four templates (Oil & Gas, Cement, Mining, Power), three modalities, versioned library, Included / Out of scope / Not applicable / Unknown states.'), L('Fotos con asociación trazable, pendientes no bloqueantes, PDF real, EN/ES, persistencia local.', 'Photos with traceable links, non-blocking pending items, real PDF, EN/ES, local persistence.')])}
      ${mrow(L('Modificado', 'Changed'), 'warn', [L('Wizard: barra de etapas compacta, tarjeta de etapa con «siguiente acción», pendientes en panel a demanda y pie fijo.', 'Wizard: compact stage bar, stage card with “next action”, pending items in an on-demand panel and a fixed footer.'), L('Procesos críticos como tarjetas con tres acciones principales; recorrido organizado por proceso y área; escenarios plegables.', 'Critical processes as cards with three main actions; walkdown organized by process and area; collapsible scenarios.'), L('Foto y Hallazgo solo dentro de un assessment abierto. Idioma, tema y reinicio centralizados en Ajustes.', 'Photo and Finding only inside an open assessment. Language, theme and reset centralized in Settings.'), L('Evidencias del caso demo: ilustraciones técnicas coherentes con bombas, PLC y medición.', 'Demo case evidence: technical illustrations consistent with pumps, PLC and metering.')])}
      ${mrow(L('Nuevo', 'New'), 'pri', [L('Acceso demo con 1 administrador y 6 ingenieros ejecutores; cambio de usuario.', 'Demo sign-in with 1 administrator and 6 field engineers; user switching.'), L('Dashboard de gestión por usuario (global para el administrador), con responsable, equipo, etapa, avance y pendientes.', 'Per-user management dashboard (global for the administrator), with lead, team, stage, progress and pending items.'), L('Nuevo assessment con modalidad primero; responsable y evaluadores por assessment; asignación y reasignación.', 'New assessment with modality first; per-assessment lead and assessors; assign and reassign.'), L('Autor y fecha en respuestas, fotos, hallazgos y decisiones; historial de cambios; permisos configurables; menú colapsable.', 'Author and date on answers, photos, findings and decisions; change history; configurable permissions; collapsible menu.')])}
    </tbody></table></div>`;
    return `<div class="hello"><div><h1>${L('Ajustes', 'Settings')}</h1><p>${L('Preferencias, acceso y alcance del demo en un solo lugar.', 'Preferences, access and demo scope in one place.')}</p></div></div>
      <div class="grid2">
        <section class="box"><div class="box-head"><h3>${L('Idioma', 'Language')}</h3></div><div class="box-body"><div class="row">${U.langSwitch()}<span class="small mut">${L('Interfaz, caso demo e informe PDF. El texto escrito por usuarios no se traduce.', 'Interface, demo case and PDF report. User-typed text is not translated.')}</span></div></div></section>
        <section class="box"><div class="box-head"><h3>${L('Apariencia', 'Appearance')}</h3></div><div class="box-body"><div class="seg" role="group" aria-label="${L('Tema', 'Theme')}">${[['light', L('Claro', 'Light')], ['dark', L('Oscuro', 'Dark')], ['system', L('Sistema', 'System')]].map(([k, l]) => `<button data-act="theme-set" data-t="${k}" aria-pressed="${th === k}">${l}</button>`).join('')}</div></div></section>
      </div>
      <section class="box"><div class="box-head"><h3>${L('Acceso y roles', 'Access and roles')}</h3><span class="pill demo">${L('Autenticación simulada', 'Simulated authentication')}</span><p>${L('Identidad (quién es), rol global (Administrador o Ingeniero ejecutor) y responsabilidad por assessment (Responsable, Evaluador) son cosas distintas. Preparado para Microsoft Entra ID; no está conectado.', 'Identity (who you are), global role (Administrator or Field engineer) and per-assessment responsibility (Lead, Assessor) are different things. Prepared for Microsoft Entra ID; not connected.')}</p></div>
        <div class="scroll-x"><table style="min-width:520px"><thead><tr><th>${L('Persona', 'Person')}</th><th>${L('Rol global', 'Global role')}</th><th>${L('Responsable de', 'Lead of')}</th><th>${L('Evaluador en', 'Assessor in')}</th></tr></thead><tbody>${users}</tbody></table></div></section>
      <section class="box"><div class="box-head"><h3>${L('Permisos de los ingenieros ejecutores', 'Field engineer permissions')}</h3>${admin ? '' : `<span class="small mut">${L('Solo el administrador puede cambiarlos', 'Only the administrator can change them')}</span>`}<p>${L('El administrador siempre puede hacer todo.', 'The administrator can always do everything.')}</p></div><div>
        ${perm('create', L('Crear assessments', 'Create assessments'), L('Iniciar un assessment nuevo desde el dashboard.', 'Start a new assessment from the dashboard.'))}
        ${perm('assign', L('Gestionar evaluadores (responsables)', 'Manage assessors (leads)'), L('El responsable de un assessment puede agregar o quitar evaluadores. Cambiar el responsable es exclusivo del administrador; los evaluadores no ven «Asignar».', 'An assessment lead can add or remove assessors. Changing the lead is administrator-only; assessors do not see “Assign”.'))}
        ${perm('library', L('Editar biblioteca y plantillas', 'Edit library and templates'), L('Preguntas, modalidades, plantillas y reglas de cobertura fotográfica.', 'Questions, modalities, templates and photo coverage rules.'))}</div></section>
      <section class="box"><div class="box-head"><h3>${L('Datos de demostración', 'Demo data')}</h3></div><div class="box-body"><div class="row"><button class="btn danger" data-act="reset" ${admin ? '' : 'disabled'}>${ic('reset')}${L('Reiniciar datos demo', 'Reset demo data')}</button><span class="small mut">${admin ? L('Elimina assessments, fotos y cambios guardados en este navegador. Pide confirmación.', 'Deletes assessments, photos and changes saved in this browser. Asks for confirmation.') : L('Solo el administrador puede reiniciar los datos.', 'Only the administrator can reset the data.')}</span></div></div></section>
      <section class="box"><div class="box-head"><h3>${L('Catálogo industrial', 'Industry catalog')}</h3><p>${L('Procesos, áreas, sistemas OT, dependencias y controles sugeridos por industria, versionados. Se administran en Biblioteca.', 'Processes, areas, OT systems, dependencies and controls suggested per industry, versioned. Managed in the Library.')}</p></div><div class="box-body">${C.can('library') ? `<button class="btn ghost" data-act="go-catalog">${ic('book', 'sm')}${L('Abrir catálogo en Biblioteca', 'Open catalog in Library')}</button>` : `<span class="small mut">${L('Requiere permiso de biblioteca', 'Requires library permission')}</span>`}</div></section>
      <h3 class="grp">${L('Alcance y limitaciones del demo', 'Demo scope and limitations')}</h3>
      ${U.dt('s-mx', L('Funcionalidades conservadas, modificadas y nuevas', 'Features kept, changed and new'), matrix)}
      ${U.dt('s-real', L('Qué es real y qué es simulado', 'What is real and what is simulated'), U.aboutBody())}
      ${U.dt('s-kairos', L('Datos reutilizados de Kairos Ecosistema', 'Data reused from Kairos Ecosistema'), li([L('Nombres y fotos de 7 colaboradores: Gustavo Ramírez (administrador aquí; Dirección en Kairos) y seis ingenieros ejecutores: Kenya Sánchez, Cristian Pérez, Juan Menco, Kevin Peña, Laura Posso y Simón Giraldo.', 'Names and photos of 7 collaborators: Gustavo Ramírez (administrator here; Management in Kairos) and six field engineers: Kenya Sánchez, Cristian Pérez, Juan Menco, Kevin Peña, Laura Posso and Simón Giraldo.'), L('Identidad visual: paleta, tipografía Poppins, menú lateral colapsable y pantalla de acceso partida.', 'Visual identity: palette, Poppins type, collapsible side menu and split sign-in screen.'), L('No se reutilizaron proyectos, reservas ni datos operativos de Kairos.', 'No Kairos projects, bookings or operational data were reused.')]))}
      ${U.dt('s-back', L('Fuera del alcance del artefacto: servidor, Entra ID y concurrencia', 'Outside the artifact scope: server, Entra ID and concurrency'), li([L('Servidor y base de datos compartida: hoy todo vive en este navegador.', 'Server and shared database: today everything lives in this browser.'), L('Microsoft Entra ID: inicio de sesión real, sincronización de personas y roles.', 'Microsoft Entra ID: real sign-in, people and role sync.'), L('Concurrencia real: sincronización entre dispositivos, bloqueo o fusión de ediciones simultáneas y prevención de sobrescrituras.', 'Real concurrency: sync across devices, locking or merging simultaneous edits, and overwrite prevention.'), L('Permisos validados en servidor, almacenamiento seguro de fotos y eliminación de metadatos.', 'Server-validated permissions, secure photo storage and metadata removal.')]))}
      ${U.dt('s-val', L('Aspectos que requieren su validación', 'Items that need your validation'), li([L('Si los tres permisos configurables son los correctos y sus valores por defecto.', 'Whether the three configurable permissions are the right ones, and their defaults.'), L('Si un ingeniero ejecutor debe ver solo sus assessments o todo el portafolio en lectura.', 'Whether a field engineer should see only their assessments or the whole portfolio read-only.'), L('Quién puede aprobar el informe (hoy: cualquier integrante con la revisión completa).', 'Who can approve the report (today: any member once review is complete).'), L('Textos de alcance y entregables por modalidad, tomados de la propuesta v0.1.', 'Scope and deliverable texts per modality, taken from proposal v0.1.'), L('Evaluación y resultados: quedó más clara la presentación; la revisión funcional adicional sigue pendiente.', 'Assessment and results: presentation is clearer; the additional functional review is still pending.')]))}`;
  };

  // ---------- Modals ----------
  U.openModal = (type, data) => { U.modal = { type, data: data || {} }; U.renderModal(); };
  U.closeModal = () => { U.modal = null; document.getElementById('layer').innerHTML = ''; };
  U.renderModal = function () {
    const Ly = document.getElementById('layer'); const M = U.modal; if (!M) { Ly.innerHTML = ''; return; }
    const a = C.cur(); if (!a && !['user', 'confirm', 'qedit', 'assign', 'catitem', 'libximp'].includes(M.type)) { U.modal = null; Ly.innerHTML = ''; return; } const f = U.modals[M.type](a, M.data);
    Ly.innerHTML = `<div class="scrim ${f.drawer ? 'drawer' : ''}" data-act="scrim"><div class="modal ${f.wide ? 'wide' : ''}" role="dialog" aria-modal="true" aria-labelledby="mdl-t"><div class="modal-h"><h2 id="mdl-t">${f.title}</h2><button class="icon-btn" data-act="modal-close" aria-label="${L('Cerrar', 'Close')}">${ic('x')}</button></div><div class="modal-b">${f.body}</div>${f.foot ? `<div class="modal-f">${f.foot}</div>` : ''}</div></div>`;
    const first = Ly.querySelector('[data-autofocus]') || Ly.querySelector('.modal-b input, .modal-b select, .modal-b textarea, .modal-b button');
    if (first) first.focus({ preventScroll: true });
  };
  const linkSelects = (a, Lk) => {
    const sel = (k, lbl, opts) => `<div class="field"><label for="lk-${k}">${lbl}</label><select id="lk-${k}">${U.opt('', '—', Lk[k] || '')}${opts.map(([v, l]) => U.opt(v, l, Lk[k] || '')).join('')}</select></div>`;
    const ev = C.evaluate(a);
    return `<div class="grid2">${sel('area', L('Área', 'Area'), a.areas.map(x => [x.id, tx(x.name)]))}${sel('asset', L('Activo', 'Asset'), a.assets.map(x => [x.id, x.tag + ' · ' + tx(x.name)]))}${sel('q', L('Pregunta', 'Question'), ev.app.map(x => [x.q.id, x.q.id + ' · ' + tx(x.q.text).slice(0, 60)]))}${sel('finding', L('Hallazgo', 'Finding'), a.findings.map(x => [x.id, x.id + ' · ' + tx(x.title)]))}${sel('scenario', L('Escenario de riesgo', 'Risk scenario'), a.scenarios.map(x => [x.id, x.id + ' · ' + tx(x.title).slice(0, 60)]))}${a.systems && a.systems.length ? sel('system', L('Sistema OT', 'OT system'), a.systems.map(x => [x.id, tx(x.name)])) : ''}${a.deps.length ? sel('dep', L('Dependencia', 'Dependency'), a.deps.map(x => [x.id, C.nodeLbl(a, x.from) + ' → ' + C.nodeLbl(a, x.to)])) : ''}</div>`;
  };
  U.readLinks = () => { const o = {}; ['area', 'asset', 'system', 'dep', 'q', 'finding', 'scenario'].forEach(k => { const v = (document.getElementById('lk-' + k) || {}).value; if (v) o[k] = v; }); return o; };
  U.modals = {
    capture(a, d) {
      const cap = U.cap || {};
      return { title: L('Capturar evidencia fotográfica', 'Capture photo evidence'), wide: true, body: `
        <div class="drop ${cap.url ? 'has' : ''}">${cap.url ? `<img src="${cap.url}" alt="${L('Vista previa', 'Preview')}">` : `${ic('camera')}<b>${L('Tome una foto o cargue un archivo', 'Take a photo or upload a file')}</b><span class="small mut">${L('En móvil, «Tomar foto» abre la cámara si el navegador lo permite. Las imágenes se optimizan a 1600 px.', 'On mobile, “Take photo” opens the camera if the browser allows it. Images are optimized to 1600 px.')}</span>`}
          <div class="row"><label class="btn primary sm" for="cap-cam">${ic('camera', 'sm')}${L('Tomar foto', 'Take photo')}</label><input class="sr" type="file" id="cap-cam" accept="image/*" capture="environment" data-cap="1"><label class="btn ghost sm" for="cap-file">${ic('image', 'sm')}${L('Cargar archivo', 'Upload file')}</label><input class="sr" type="file" id="cap-file" accept="image/*" data-cap="1"></div>${cap.info ? `<span class="small mut">${h(cap.info)}</span>` : ''}${cap.err ? `<span class="small" style="color:var(--err-ink)">${h(cap.err)}</span>` : ''}</div>
        <div class="field"><label for="cp-title">${L('Título', 'Title')} *</label><input id="cp-title" value="${h(cap.title || '')}" placeholder="${L('p. ej. Placa de P-101B', 'e.g. P-101B nameplate')}"></div><p class="small mut">${ic('clock', 'sm')} ${h(C.me().name)} · ${L('autor y fecha automáticos', 'automatic author and date')}</p>
        <div class="field"><label for="cp-cap">${L('Descripción / pie de foto', 'Description / caption')}</label><textarea id="cp-cap">${h(cap.caption || '')}</textarea></div>
        <div class="sec-title">${L('Asociación trazable', 'Traceable links')}</div>${linkSelects(a, d.links || {})}
        <label class="check"><input type="checkbox" id="cp-rep" checked><span>${L('Incluir en el informe PDF (puede excluirse luego sin eliminar la evidencia)', 'Include in the PDF report (can be excluded later without deleting the evidence)')}</span></label>`,
        foot: `<button class="btn ghost" data-act="modal-close">${L('Cancelar', 'Cancel')}</button><button class="btn primary" data-act="cap-save" ${cap.blob ? '' : 'disabled'}>${ic('check', 'sm')}${L('Guardar evidencia', 'Save evidence')}</button>` };
    },
    justify(a, d) {
      const r = C.photoReqs(a).find(x => x.key === d.key) || { label: d.key };
      return { title: L('Registrar foto faltante', 'Record missing photo'), body: `<p>${h(r.label)}</p><div class="note-info">${ic('info')}<span>${L('La nota explica la ausencia; no crea evidencia ni elimina la incertidumbre. El pendiente queda «por revisar» y aparecerá en las limitaciones del informe.', 'The note explains the absence; it does not create evidence or remove uncertainty. The item stays “to review” and will appear in the report limitations.')}</span></div>
        <div class="field"><label for="js-reason">${L('Motivo', 'Reason')}</label><select id="js-reason">${D.PHOTO_REASONS.map(x => U.opt(x, tx(x))).join('')}</select></div><div class="field"><label for="js-note">${L('Nota breve', 'Short note')} *</label><textarea id="js-note" placeholder="${L('p. ej. Equipo en mantenimiento con bloqueo; se programa para la próxima visita', 'e.g. Equipment under maintenance lockout; scheduled for next visit')}"></textarea></div><div class="field"><label for="js-by">${L('Registrado por', 'Recorded by')}</label><input id="js-by" value="${h(C.me().name)}" readonly></div>`,
        foot: `<button class="btn ghost" data-act="modal-close">${L('Cancelar', 'Cancel')}</button><button class="btn primary" data-act="just-save" data-key="${h(d.key)}">${L('Registrar y continuar', 'Record and continue')}</button>` };
    },
    finding(a, d) {
      const ev = C.evaluate(a);
      return { title: L('Registrar hallazgo', 'Record finding'), body: `<div class="field"><label for="fd-title">${L('Hallazgo', 'Finding')} *</label><input id="fd-title" placeholder="${L('Descripción corta', 'Short description')}"></div><div class="field"><label for="fd-desc">${L('Detalle', 'Detail')}</label><textarea id="fd-desc"></textarea></div>
        <div class="field"><span class="lbl">${L('Activos involucrados', 'Assets involved')}</span><div class="cbs">${a.assets.map(x => `<label><input type="checkbox" class="fd-as" value="${x.id}" ${d.asset === x.id ? 'checked' : ''}>${h(x.tag)}</label>`).join('') || `<span class="small mut">${L('Sin activos registrados.', 'No assets recorded.')}</span>`}</div></div>
        <div class="field"><label for="fd-q">${L('Pregunta de origen', 'Source question')}</label><select id="fd-q">${U.opt('', '—')}${ev.app.map(x => U.opt(x.q.id, x.q.id + ' · ' + tx(x.q.text).slice(0, 70), d.q || '')).join('')}</select></div>`,
        foot: `<button class="btn ghost" data-act="modal-close">${L('Cancelar', 'Cancel')}</button><button class="btn primary" data-act="fd-save">${L('Registrar hallazgo', 'Record finding')}</button>` };
    },
    lightbox(a, d) {
      const p = a.photos.find(x => x.id === d.id); if (!p) return { title: L('Foto', 'Photo'), body: '' };
      return { title: h(tx(p.title)), wide: true, body: `<div class="lightbox"><img src="${C.photoURL(p)}" alt="${h(tx(p.title))}"><div style="display:flex;flex-direction:column;gap:12px">
        <div class="field"><label for="lb-title">${L('Título', 'Title')}</label><input id="lb-title" value="${h(tx(p.title))}"></div><div class="field"><label for="lb-cap">${L('Pie de foto', 'Caption')}</label><textarea id="lb-cap">${h(tx(p.caption))}</textarea></div>
        <div class="grid2"><div class="field"><label for="lb-rev">${L('Estado de revisión', 'Review status')}</label><select id="lb-rev">${['Por revisar', 'Aprobada', 'Requiere nueva toma'].map(x => U.opt(x, tx(x), p.review)).join('')}</select></div><div class="field"><span class="lbl">${L('Fecha y autor', 'Date and author')}</span><span class="small">${C.fmtDate(p.ts, true)} · ${h(p.author)}</span></div></div>
        <label class="check"><input type="checkbox" id="lb-rep" ${p.inReport ? 'checked' : ''}><span>${L('Incluir en el informe', 'Include in report')}</span></label><label class="check"><input type="checkbox" id="lb-cov" ${p.cover ? 'checked' : ''}><span>${L('Usar como foto de portada', 'Use as cover photo')}</span></label>
        <div class="sec-title">${L('Asociación', 'Links')}</div>${linkSelects(a, p.links || {})}<p class="small mut">${L('ID de evidencia', 'Evidence ID')} ${p.id}${p.src.startsWith('asset:') ? L(' · imagen ilustrativa de demostración', ' · illustrative demo image') : ''}</p></div></div>`,
        foot: `<button class="btn ghost" data-act="modal-close">${L('Cerrar', 'Close')}</button><button class="btn primary" data-act="lb-save" data-id="${p.id}">${L('Guardar cambios', 'Save changes')}</button>` };
    },
    scenario(a, d) {
      const s = a.scenarios.find(x => x.id === d.id); const l = C.LEVEL(s.C, s.P);
      const ph = a.photos.filter(p => p.links && (p.links.scenario === s.id || s.findings.includes(p.links.finding)));
      const recs = a.recs.filter(r => r.sc.includes(s.id)); const fnd = a.findings.filter(f => s.findings.includes(f.id));
      return { title: s.id + ' · ' + h(tx(s.title)), wide: true, body: `<div class="row">${U.lv(l)}<span class="pill">${h(C.procName(a, s.proc))}</span><span class="pill">${L('Confianza', 'Confidence')}: ${h(tx(s.conf))}</span><span class="pill">C ${s.C || '—'} · P ${s.P || '—'}</span></div>
        <div class="grid2"><div><div class="sec-title">${L('Consecuencia', 'Consequence')}</div><p class="small">${h(tx(s.justC) || L('Sin justificación', 'No justification'))}</p></div><div><div class="sec-title">${L('Probabilidad con controles', 'Likelihood with controls')}</div><p class="small">${h(tx(s.justP) || L('Pendiente de evaluación', 'Pending assessment'))}</p></div></div>
        <div><div class="sec-title">${L('Controles', 'Controls')}</div>${s.controls.map(c => `<p class="small">${h(tx(c.name))} · <b>${h(tx(c.st))}</b></p>`).join('') || `<p class="small mut">${L('Sin controles.', 'No controls.')}</p>`}</div>
        <div><div class="sec-title">${L('Trazabilidad', 'Traceability')}</div>${fnd.map(f => `<p class="small"><b>${f.id}</b> ${h(tx(f.title))}${f.q ? ` ← ${L('respuesta', 'answer')} <b>${f.q}</b>: ${h(tx((a.answers[f.q] || {}).value) || '—')}` : ''} · ${L('activos', 'assets')} ${f.assets.map(x => C.assetLbl(a, x)).join(', ')}</p>`).join('') || `<p class="small mut">${L('Sin hallazgos vinculados.', 'No linked findings.')}</p>`}</div>
        <div><div class="sec-title">${L('Evidencia fotográfica', 'Photo evidence')}</div><div class="gallery">${ph.map(p => U.photoCard(a, p)).join('') || `<p class="small mut">${L('Sin fotos vinculadas.', 'No linked photos.')}</p>`}</div></div>
        <div><div class="sec-title">${L('Recomendaciones', 'Recommendations')}</div>${recs.map(r => `<p class="small"><b>${r.id}</b> ${h(tx(r.title))} · ${h(tx(r.hz))}</p>`).join('') || `<p class="small mut">${L('Sin recomendaciones.', 'No recommendations.')}</p>`}</div>`,
        foot: `<button class="btn ghost" data-act="modal-close">${L('Cerrar', 'Close')}</button><button class="btn primary" data-act="go" data-stage="6" data-target="scn-${s.id}">${L('Abrir en Evaluación', 'Open in Assessment')}</button>` };
    },
    assign(a0, d) {
      const a = C.S.assessments.find(x => x.id === d.id) || a0;
      return { title: L('Responsable y equipo', 'Lead and team') + ' · ' + h(tx(a.cfg.plant) || a.code), body: `<p class="small mut">${L('Asignación propia de este assessment. Queda registrada en el historial.', 'Assignment specific to this assessment. It is recorded in the history.')}</p>
        <div class="field"><label for="as-lead">${L('Responsable', 'Lead')}</label><select id="as-lead" ${C.isAdmin() ? '' : 'disabled'}>${C.USERS.map(u => U.opt(u.id, u.name + ' · ' + C.roleName(u), a.leadId)).join('')}</select>${C.isAdmin() ? '' : `<span class="hint">${L('Solo el administrador puede cambiar el responsable. Usted puede gestionar los evaluadores.', 'Only the administrator can change the lead. You can manage the assessors.')}</span>`}</div>
        <div class="field"><span class="lbl">${L('Evaluadores', 'Assessors')}</span><div class="people-pick">${C.USERS.map(u => `<label class="pp ${u.id === a.leadId ? 'is-lead' : ''}"><input type="checkbox" class="as-team" value="${u.id}" ${(a.team || []).includes(u.id) && u.id !== a.leadId ? 'checked' : ''} ${u.id === a.leadId ? 'disabled' : ''}>${U.av(u.id, 'sm')}<span class="pp-n">${h(u.name)}<em class="pp-tag">${L('Responsable', 'Lead')}</em></span></label>`).join('')}</div></div>`,
        foot: `<button class="btn ghost" data-act="modal-close">${L('Cancelar', 'Cancel')}</button><button class="btn primary" data-act="assign-save" data-id="${a.id}">${L('Guardar asignación', 'Save assignment')}</button>` };
    },
    user() {
      const me = C.me();
      return { title: L('Cuenta', 'Account'), body: `<div class="ac-lead">${U.av(me.id)}<span><small>${C.roleName(me)}</small><b>${h(me.name)}</b></span></div>
        <div class="sec-title">${L('Cambiar de usuario (demo)', 'Switch user (demo)')}</div>
        <div class="roles">${C.USERS.filter(u => u.id !== me.id).map(u => `<button class="choice sm" data-act="login" data-id="${u.id}">${U.av(u.id, 'sm')}<span><b>${h(u.name)}</b><span class="d">${C.roleName(u)}</span></span>${ic('chev', 'sm')}</button>`).join('')}</div>
        <p class="hint">${L('Acceso simulado; en producción será Microsoft Entra ID.', 'Simulated sign-in; in production it will be Microsoft Entra ID.')}</p>`,
        foot: `<button class="btn ghost" data-act="nav" data-view="settings">${ic('gear', 'sm')}${L('Ajustes', 'Settings')}</button><button class="btn danger" data-act="logout">${L('Cerrar sesión', 'Sign out')}</button>` };
    },
    pending(a) {
      const ev = C.evaluate(a);
      return { title: L('Progreso y pendientes', 'Progress and pending items') + ' · ' + ev.pct + ' %', drawer: true, body: U.rail(a, ev) };
    },
    confirm(a, d) { return { title: h(d.title), body: `<p>${h(d.msg)}</p>`, foot: `<button class="btn ghost" data-act="modal-close">${L('Cancelar', 'Cancel')}</button><button class="btn ${d.danger ? 'danger' : 'primary'}" data-act="confirm-yes">${h(d.yes || L('Confirmar', 'Confirm'))}</button>` }; },
    qedit(a, d) {
      const lib = C.S.lib; const q = d.id ? lib.questions.find(x => x.id === d.id) : { id: '', text: '', dim: D.DIMS[0], ind: ['oilgas'], mods: D.ALL.slice(), order: 30, active: true, req: true, pol: 'control', proc: null, cond: null, ev: false };
      const procs = []; Object.keys(lib.templates).forEach(k => lib.templates[k].processes.forEach(p => procs.push([p.key, C.indName(k) + ' · ' + tx(p.name)])));
      return { title: d.id ? L('Editar ', 'Edit ') + q.id + ' (v' + q.v + ' → v' + (q.v + 1) + ')' : L('Nueva pregunta', 'New question'), wide: true, body: `
        <div class="field"><label for="qe-text">${L('Pregunta', 'Question')} *</label><textarea id="qe-text" data-autofocus>${h(tx(q.text))}</textarea><span class="hint">${L('Redacte de modo que «Sí» indique un control presente, o márquela como de contexto.', 'Phrase it so “Yes” means a control is present, or mark it as context.')}</span></div>
        <div class="grid3"><div class="field"><label for="qe-dim">${L('Dimensión', 'Dimension')}</label><select id="qe-dim">${D.DIMS.map(x => U.opt(x, tx(x), q.dim)).join('')}</select></div><div class="field"><label for="qe-pol">${L('Tipo', 'Type')}</label><select id="qe-pol">${U.opt('control', L('Control (puntúa en el radar)', 'Control (scored in radar)'), q.pol)}${U.opt('contexto', L('Contexto (no puntúa)', 'Context (not scored)'), q.pol)}</select></div><div class="field"><label for="qe-order">${L('Orden en el núcleo', 'Order in core')}</label><input id="qe-order" type="number" value="${q.order}"></div></div>
        <div class="field"><span class="lbl">${L('Industrias', 'Industries')}</span><div class="cbs"><label><input type="checkbox" class="qe-ind" value="*" ${q.ind.includes('*') ? 'checked' : ''}>${L('Común a todas', 'Common to all')}</label>${D.INDUSTRIES.map(i => `<label><input type="checkbox" class="qe-ind" value="${i.key}" ${q.ind.includes(i.key) ? 'checked' : ''}>${h(tx(i.name))}</label>`).join('')}</div></div>
        <div class="field"><span class="lbl">${L('Modalidades', 'Modalities')}</span><div class="cbs">${D.ALL.map(m => `<label><input type="checkbox" class="qe-mod" value="${m}" ${q.mods.includes(m) ? 'checked' : ''}>${h(C.modName(lib.modalities[m]))}</label>`).join('')}</div></div>
        <div class="grid2"><div class="field"><label for="qe-proc">${L('Proceso asociado', 'Linked process')}</label><select id="qe-proc">${U.opt('', L('Ninguno (general)', 'None (general)'), q.proc || '')}${procs.map(([k, l]) => U.opt(k, l, q.proc || '')).join('')}</select></div>
        <div class="field"><label for="qe-cq">${L('Condición: mostrar solo si…', 'Condition: show only if…')}</label><select id="qe-cq">${U.opt('', L('Sin condición (núcleo)', 'No condition (core)'), (q.cond && q.cond.q) || '')}${lib.questions.filter(x => x.id !== q.id).map(x => U.opt(x.id, x.id + ' · ' + tx(x.text).slice(0, 50), (q.cond && q.cond.q) || '')).join('')}</select></div></div>
        <div class="field"><span class="lbl">${L('…la respuesta a esa pregunta es', '…the answer to that question is')}</span><div class="cbs">${['Sí', 'No', 'Desconocido', 'No aplica'].map(v => `<label><input type="checkbox" class="qe-cin" value="${v}" ${q.cond && q.cond.in && q.cond.in.includes(v) ? 'checked' : ''}>${tx(v)}</label>`).join('')}</div></div>
        <div class="cbs"><label><input type="checkbox" id="qe-req" ${q.req ? 'checked' : ''}>${L('Esencial (cuenta para completitud)', 'Essential (counts toward completeness)')}</label><label><input type="checkbox" id="qe-act" ${q.active ? 'checked' : ''}>${L('Activa', 'Active')}</label></div>
        <p class="hint">${L(`Se guardará en la biblioteca v${lib.version + 1}. Aplica a assessments nuevos; los existentes conservan su versión.`, `Will be saved in library v${lib.version + 1}. Applies to new assessments; existing ones keep their version.`)}</p>`,
        foot: `<button class="btn ghost" data-act="modal-close">${L('Cancelar', 'Cancel')}</button><button class="btn primary" data-act="qe-save" data-id="${h(d.id || '')}">${L('Guardar en biblioteca', 'Save to library')}</button>` };
    }
  };
})();
